        current_count = data['cnt_maximal_cocktails']

        current_edges_set = set(frozenset(edge) for edge in edges)
        candidate_edges = []
        for u, v in combinations(nodes, 2):
            if frozenset((u, v)) not in current_edges_set:
                candidate_edges.append((u, v))

        valid_edges = []
        for edge in candidate_edges:
            new_edges = edges + [edge]
            G = nx.Graph()
            G.add_nodes_from(nodes)
            G.add_edges_from(new_edges)
            CG = nx.complement(G)
